cat app/src/main/java/com/example/presentation/library/LibraryScreen.kt | \
sed -e 's/fun LibraryScreen(viewModel: LibraryViewModel)/fun LibraryScreen(viewModel: LibraryViewModel, onNavigateToLocalAudio: () -> Unit = {})/g' \
    -e 's/LazyColumn(verticalArrangement = Arrangement.spacedBy(16.dp)) {/LazyColumn(verticalArrangement = Arrangement.spacedBy(16.dp)) {\n            item {\n                Row(\n                    modifier = Modifier\n                        .fillMaxWidth()\n                        .clip(RoundedCornerShape(8.dp))\n                        .background(SurfaceColor)\n                        .clickable { onNavigateToLocalAudio() }\n                        .padding(14.dp),\n                    verticalAlignment = Alignment.CenterVertically\n                ) {\n                    Box(\n                        modifier = Modifier\n                            .size(48.dp)\n                            .clip(RoundedCornerShape(8.dp))\n                            .background(YouTubeRed.copy(alpha = 0.1f)),\n                        contentAlignment = Alignment.Center\n                    ) {\n                        Icon(Icons.Default.FolderOpen, contentDescription = "Yerel Klasörler", tint = YouTubeRed)\n                    }\n                    Spacer(modifier = Modifier.width(14.dp))\n                    Column(modifier = Modifier.weight(1f)) {\n                        Text("Cihaz Klasörleri (SAF)", color = TextPrimary, fontSize = 16.sp, fontWeight = FontWeight.SemiBold)\n                        Text("Yerel ses dosyalarını Room DB ile senkronize et", color = TextSecondary, fontSize = 13.sp)\n                    }\n                    Icon(Icons.Default.KeyboardArrowRight, contentDescription = null, tint = TextSecondary)\n                }\n            }/g' \
> new_LibraryScreen.kt
mv new_LibraryScreen.kt app/src/main/java/com/example/presentation/library/LibraryScreen.kt
